// natively everywhere, so the tab is named after it.
type InterfacesModel struct {
	width  int
	height int

	table   datatable.Model[netiface.Interface]
	spinner spinner.Model

	loading bool
	// lastOK dates the rows, and loadErr says the most recent read failed.
	//
	// A failed read keeps the rows on screen: they are not wrong, they are
	// dated, and dropping them would leave the tab empty over a transient
	// failure. What has to be said is their age — a footer *message* cannot
	// carry it, since it expires after three seconds (Rule 128).
	lastOK  time.Time
	loadErr bool

	// footer is this tab's own message line. Each tab keeps one: a shared
	// instance would let a message set here outlive the switch away from it.
	footer components.FooterMessage
}

func newInterfacesModel() *InterfacesModel {
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	return &InterfacesModel{
		loading: true,
		spinner: sp,
		table: datatable.New(datatable.Config[netiface.Interface]{
			Columns:    interfaceColumns(),
			SortColumn: 0,
		}),
	}
		return theme.StatusOKStyle
	}
}

// initInterfaces returns the initial commands: one read, and the spinner.
func (im *InterfacesModel) initInterfaces() tea.Cmd {
	return tea.Batch(fetchInterfacesCmd(), im.spinner.Tick)
}

// InEditMode reports whether a text field has the keyboard.
func (im *InterfacesModel) InEditMode() bool {
	return im.table.FilterBar().InEditMode()
}

func (im *InterfacesModel) resize(width, height int) {
	im.width = width
	im.height = height
	// The full viewport width, borders included: Resize subtracts them itself, so
	// the `-2` this used to carry subtracted them twice and the selected row
	// stopped two cells short of the right border at every width. The
	// `max(..., 20)` went with it: a floor above what the terminal has makes the
	// table wider than the viewport, which is the overflow Rule 116 is about, and
	// a narrow terminal is now handled by dropping columns (§3.45).
	im.table.Resize(width, max(height, 3))
}

func (im *InterfacesModel) update(msg tea.Msg) (*InterfacesModel, tea.Cmd) {
	switch msg := msg.(type) {
	case ifaceDataMsg:
		return im.handleData(msg)
	case spinner.TickMsg:
		if !im.loading {
			return im, nil
		}
		var cmd tea.Cmd
		im.spinner, cmd = im.spinner.Update(msg)
		// The load is reported in the footer, so the frame has to reach it —
		// a spinner stuck on frame zero reads as a hang (Rule 139).
		im.footer.SetSpinnerFrame(im.spinner.View())
		return im, cmd
	case tea.KeyPressMsg:
		return im.handleKey(msg)
	case tea.PasteMsg:
		// Only the filter bar takes text; otherwise the paste is dropped (Rule 111).
		if im.table.FilterBar().InEditMode() {
			return im, im.table.Update(msg)
		}
		return im, nil
	}
	im.footer.Handle(msg)
	return im, nil
}

func (im *InterfacesModel) handleData(msg ifaceDataMsg) (*InterfacesModel, tea.Cmd) {
	im.loading = false

	if msg.err != nil {
		log.Printf("ERROR [netdiag/interfaces] list: %v", msg.err)
		im.loadErr = true
		return im, nil
	}

	im.loadErr = false
	im.lastOK = time.Now()
	im.table.SetItems(msg.interfaces)
	return im, nil
}

func (im *InterfacesModel) handleKey(msg tea.KeyPressMsg) (*InterfacesModel, tea.Cmd) {
	if im.table.FilterBar().InEditMode() {
		return im, im.table.Update(msg)
	}

	if msg.String() == "ctrl+r" {
		im.loading = true
		return im, tea.Batch(fetchInterfacesCmd(), im.spinner.Tick)
	}

	return im, im.table.Update(msg)
}

// statusLine is what this tab derives on every frame.
//
// Staleness outranks the load: a read that failed makes the rows on screen
// dated, and that has to keep being said while the next one runs.
func (im *InterfacesModel) statusLine() components.Status {
	if im.loadErr {
		return components.Status{Text: im.staleLabel(), Level: components.LevelError}
	}
	if im.loading {
		return components.Status{Text: "Reading network interfaces...", Spinner: true}
	}
	return components.Status{}
}

// staleLabel dates the rows on screen, or says there are none to date.

	// Form inputs
	targetInput    textinput.Model
	portInput      textinput.Model
	dnsServerInput textinput.Model
	focusedField   int

	// Running state
	spinner    spinner.Model
	runGen     int // incremented each run; results from a superseded run are dropped
	runStage   netcheck.StageID
	// first nameserver out of /etc/resolv.conf, which does not exist on Windows.
	dnsIn.Placeholder = "system resolver"
	dnsIn.CharLimit = 64

	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	return &Model{
		config:          cfg,
		state:           StateInput,
		activeTab:       tabDiagnostics,
		portsModel:      newPortsModel(time.Duration(cfg.Network.PortsRefreshInterval) * time.Second),
		interfacesModel: newInterfacesModel(),
		forwardModel:    newForwardModel(),
		targetInput:     targetIn,
		portInput:       portIn,
		dnsServerInput:  dnsIn,
		focusedField:    fieldTarget,
		spinner:         sp,
		filterBar:       components.NewFilterBarWithTokens([]components.FilterToken{{Label: problemsToken}}),
		checksTable: datatable.New(datatable.Config[netcheck.Check]{
			Columns: checkColumns(),

	m.runGen++
	m.state = StateRunning
	m.results = netcheck.Results{}
	m.verdict = netcheck.Unknown
	m.runStep = 0
	m.totalSteps = len(netcheck.Steps())
	m.runStage = netcheck.Steps()[0]

	return m, tea.Batch(m.spinner.Tick, runStageCmd(m.runGen, tg, m.checkSettings(), 0, netcheck.Results{}))
}

// runStageCmd runs one stage of the pipeline and reports the accumulated
// Update implements tea.Model
func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.resizeInputs()
		m.filterBar.Resize(msg.Width)
		m.rebuildChecksTable()
		m.resizeDetailsViewport()
		m.portsModel.resize(msg.Width, msg.Height)
		m.interfacesModel.resize(msg.Width, msg.Height)
		m.forwardModel.resize(msg.Width, msg.Height)
		return m, nil

	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)

	// The router's animation frame: only the blink phase of the Ports dot. The
	// footers keep their own spinner chains.
	case jobs.FrameMsg:
		m.portsModel.table.SetBlinkPhase(msg.Blink)
		return m, nil

	case stageDoneMsg:
		return m.handleStageDone(msg)

	// Ports sub-model messages.
	case portsTickMsg, portsDataMsg, portsKillResultMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// The terminal focus reaches the ports poll on every tab: its tick runs
	// whichever tab shows.
	case shared.TerminalFocusMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// Two tabs now ask before they act — Ports before a kill (§3.26), Forward
	// before dropping the connections a redirection is carrying — so the answer
	// goes to the tab that asked rather than to Ports unconditionally, which
	// would have confirmed a kill from the Forward tab's modal.
	case components.ConfirmModalYesMsg, components.ConfirmModalNoMsg:
		return m.routeConfirm(msg)

	// Forward sub-model messages. ChangedMsg is the router's broadcast, and it
	// reaches this view wherever it stands, on screen or not.
	case forward.ChangedMsg, forwardTickMsg, ForwardFormSubmitMsg, ForwardFormCancelMsg:
		var cmd tea.Cmd
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd

	// Topology sub-model messages
	case ifaceDataMsg:
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd

	case tea.KeyPressMsg:
		return m.handleKey(msg)

	case tea.PasteMsg:
		return m.handlePaste(msg)
	}

	// Each tab holds its own footer, so an expiry has to be offered to all
	// four: the timer fires wherever the user has since navigated.
	m.footer.Handle(msg)
	m.portsModel.footer.Handle(msg)
	m.interfacesModel.footer.Handle(msg)
	m.forwardModel.footer.Handle(msg)
	return m, nil
}

// routeConfirm hands a confirmation answer to the tab that put the modal up.
func (m *Model) routeConfirm(msg tea.Msg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	if m.activeTab == tabForward {
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd
	}
	m.portsModel, cmd = m.portsModel.update(msg)
	return m, cmd
}

func (m *Model) handleSpinnerTick(msg spinner.TickMsg) (*Model, tea.Cmd) {
	if m.state == StateRunning {
		var cmd tea.Cmd
		m.spinner, cmd = m.spinner.Update(msg)
		m.footer.SetSpinnerFrame(m.spinner.View())
		return m, cmd
	}
	if m.activeTab == tabInterfaces {
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd
	}
	return m, nil
}

// handleStageDone records one stage's answers and starts the next.
func (m *Model) handleStageDone(msg stageDoneMsg) (*Model, tea.Cmd) {
	if msg.gen != m.runGen {
		return m, nil // a superseded run
	}
	return &m.footer, m.statusLine()
}

// statusLine is what the diagnostics tab derives on every frame: a progress
// label while the pipeline walks, and nothing once it has an answer. It is a
// status rather than a footer message because it is a state, not an event —
// a message expires after three seconds and a run outlives that (Rule 128).
func (m *Model) statusLine() components.Status {
	if m.state == StateRunning {
		return components.Status{Text: m.progressLabel(), Spinner: true}
	}
	return components.Status{}
}

